import {validateBudget,budgetText} from './room-budget.mjs';
import {materialListText} from './room-shopping.mjs';
import {validateProduct,productText} from './room-products.mjs';
import {wallSegments,floorArea,perimeter,rectInside} from './room-geometry.mjs';
export const WALLS=['Северная','Восточная','Южная','Западная'];
export const LABELS={paint:'Краска',plaster:'Декоративная штукатурка',wallpaper:'Обои',laminate:'Ламинат',tile:'Плитка',stretch:'Натяжной потолок',bed:'Кровать',sofa:'Диван',desk:'Стол',wardrobe:'Шкаф',bare:'Без отделки',finished:'Готовая отделка',old:'Старый ремонт'};
export function initialProject(){return {version:1,name:'Моя гостиная',kind:'Гостиная',length:5,width:4,height:2.7,state:'bare',walls:WALLS.map((_,i)=>({finish:'paint',color:i===0?'#829078':'#e4dfd2'})),floor:{finish:'laminate',color:'#c5a77d'},ceiling:{finish:'paint',color:'#faf8f0'},openings:[{wall:0,type:'window',offset:1.6,width:1.8,height:1.4,sill:0.8},{wall:2,type:'door',offset:0.3,width:0.9,height:2.1,sill:0,hinge:'start',swing:'in'}],furniture:[{type:'sofa',x:1.2,y:0.3,width:2,depth:0.85,rotation:0}],notes:''};}
const fail=m=>{throw Error(m);};
const num=(v,min,max,label)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)fail(`${label}: допустимо ${min}–${max} м`);};
const choice=(v,values)=>{if(!values.includes(v))fail('Неизвестный вариант проекта');};
const color=v=>{if(typeof v!=='string'||!/^#[0-9a-f]{6}$/i.test(v))fail('Некорректный цвет');};
export const wallLength=(p,i)=>wallSegments(p)[i]?.length;
export function footprint(f){return f.rotation%180?{w:f.depth,d:f.width}:{w:f.width,d:f.depth};}
export function validate(p){
 if(!p||p.version!==1)fail('Неподдерживаемая версия проекта');
 for(const k of ['length','width'])num(p[k],2,20,'Размер комнаты');num(p.height,2,5,'Высота');
 if(typeof p.name!=='string'||p.name.length>80||typeof p.notes!=='string'||p.notes.length>2000)fail('Слишком длинное название или пожелания');
 choice(p.kind,['Гостиная','Спальня','Кабинет']);choice(p.state,['bare','finished','old']);
 if(p.shape!==undefined){choice(p.shape.type,['rectangle','l']);if(p.shape.type==='l'){choice(p.shape.corner,['se','sw','ne','nw']);num(p.shape.cutWidth,.5,p.length-1,'Ширина выреза');num(p.shape.cutDepth,.5,p.width-1,'Глубина выреза');}}
 validateBudget(p.budget);
 if(p.materialPlan!==undefined){if(!p.materialPlan||typeof p.materialPlan.reserve!=='number'||!Number.isFinite(p.materialPlan.reserve)||p.materialPlan.reserve<0||p.materialPlan.reserve>30)fail('Запас материалов: от 0 до 30%');}
 const count=wallSegments(p).length;if(!Array.isArray(p.walls)||p.walls.length!==count)fail('Количество стен не соответствует форме комнаты');
 p.walls.forEach(w=>{validateProduct(w,'wall');choice(w.finish,['paint','wallpaper','plaster']);color(w.color);if(w.texture!==undefined)choice(w.texture,['plain','linen','botanical','geometry','plaster']);});
 validateProduct(p.floor,'floor');validateProduct(p.ceiling,'ceiling');choice(p.floor.finish,['laminate','tile']);color(p.floor.color);if(p.floor.texture!==undefined)choice(p.floor.texture,['oak','walnut','stone','marble']);choice(p.ceiling.finish,['paint','stretch']);color(p.ceiling.color);
 if(!Array.isArray(p.openings)||p.openings.length>20||!Array.isArray(p.furniture)||p.furniture.length>30)fail('Слишком много объектов');
 p.openings.forEach((o,i)=>{choice(o.wall,Array.from({length:count},(_,i)=>i));choice(o.type,['window','door']);if(o.hinge!==undefined)choice(o.hinge,['start','end']);if(o.swing!==undefined)choice(o.swing,['in','out']);num(o.width,0.3,20,'Ширина проёма');num(o.height,0.3,5,'Высота проёма');num(o.offset,0,20,'Отступ');num(o.sill,0,5,'Подоконник');if(o.type==='door'&&o.sill!==0)fail('Дверь должна начинаться от пола');if(o.offset+o.width>wallLength(p,o.wall)+1e-8||o.sill+o.height>p.height+1e-8)fail('Проём выходит за границы стены');p.openings.slice(0,i).forEach(b=>{if(b.wall===o.wall&&o.offset<b.offset+b.width&&b.offset<o.offset+o.width&&o.sill<b.sill+b.height&&b.sill<o.sill+o.height)fail('Проёмы не должны пересекаться');});});
 p.furniture.forEach(f=>{choice(f.type,['bed','sofa','desk','wardrobe']);choice(f.rotation,[0,90,180,270]);num(f.width,0.3,5,'Ширина мебели');num(f.depth,0.3,5,'Глубина мебели');num(f.x,0,20,'Положение X');num(f.y,0,20,'Положение Y');const {w,d}=footprint(f);if(!rectInside(p,f.x,f.y,w,d))fail('Мебель выходит за границы комнаты или попадает в вырез');});return p;
}
export function quantities(p){validate(p);const floor=floorArea(p);const walls=p.walls.map((w,i)=>({ ...w,area:Math.max(0,wallLength(p,i)*p.height-p.openings.filter(o=>o.wall===i).reduce((s,o)=>s+o.width*o.height,0))}));const total=walls.reduce((s,w)=>s+w.area,0);return {floor,ceiling:floor,walls,total,plaster:walls.filter(w=>w.finish==='plaster').reduce((s,w)=>s+w.area,0),paint:walls.filter(w=>w.finish==='paint').reduce((s,w)=>s+w.area,0),wallpaper:walls.filter(w=>w.finish==='wallpaper').reduce((s,w)=>s+w.area,0),baseboard:Math.max(0,perimeter(p)-p.openings.filter(o=>o.type==='door').reduce((s,o)=>s+o.width,0))};}
export const fmt=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:2});
export function specification(p){const q=quantities(p);return `TED.renovation — концепция комнаты\n${p.name} · ${p.kind}\nРазмеры: ${fmt(p.length)} × ${fmt(p.width)} × ${fmt(p.height)} м\nФорма: ${p.shape?.type==='l'?`Г-образная, вырез ${fmt(p.shape.cutWidth)} × ${fmt(p.shape.cutDepth)} м (${p.shape.corner})`:'прямоугольная'}\nСостояние: ${LABELS[p.state]}\nПол: ${LABELS[p.floor.finish]}, образец ${p.floor.texture||(p.floor.finish==='tile'?'stone':'oak')}, ${p.floor.color}, ${fmt(q.floor)} м²\nПотолок: ${LABELS[p.ceiling.finish]}, ${p.ceiling.color}, ${fmt(q.ceiling)} м²\n${q.walls.map((w,i)=>`Стена ${i+1} (${fmt(wallLength(p,i))} м): ${LABELS[w.finish]}, образец ${w.texture||'plain'}, ${w.color}, ${fmt(w.area)} м²`).join('\n')}\nПлинтус: ${fmt(q.baseboard)} м\nПроёмы:\n${p.openings.map(o=>`Стена ${o.wall+1}: ${o.type==='door'?'дверь':'окно'} ${fmt(o.width)} × ${fmt(o.height)} м; отступ ${fmt(o.offset)} м; от пола ${fmt(o.sill)} м${o.type==='door'?`; схема открывания: ${o.swing==='out'?'наружу':'внутрь'}, петли у ${o.hinge==='end'?'конца':'начала'} проёма (уточнить на замере)`:''}`).join('\n')}\nМебель — только визуализация:\n${p.furniture.map(f=>`${LABELS[f.type]} ${fmt(f.width)} × ${fmt(f.depth)} м, X=${fmt(f.x)}, Y=${fmt(f.y)}, поворот ${f.rotation}°`).join('\n')}\nПодготовка и выравнивание стен: определить после замера.\nГрунтовка стен: предварительно ${fmt(q.total)} м²; состав системы уточнить.\nДемонтаж: ${p.state==='bare'?'не выбран':'требуется обследование, объём не определён'}.\nСтоимость работ — индивидуальная смета. Материалы, мебель, техника и авторский надзор не включены. Площади без запаса, откосы не учтены.\nМатериалы из каталога:\n${[...p.walls.map((s,i)=>['Стена '+(i+1),s]),['Пол',p.floor]].filter(([,s])=>s.product).map(([name,s])=>name+': '+productText(s)).join('\n')||'Не выбраны'}\n${materialListText(p)}\n\n${p.budget?budgetText(p):''}\n\nПожелания: ${p.notes||'нет'}\nКонцепция не заменяет замер и техническую проверку. Изображение и JSON прикрепляются к сообщению вручную.`;}
